//! Every rule the engine knows (design §5.5, ADR #19): generated by `build.rs`
//! from `rules/*.toml` (declarative) and `src/rules/<category>/*.rs` (code
//! rules, one module per file, every `impl Rule for X` registered).

use super::Rule;
use super::meta::RuleInfo;

#[allow(clippy::all)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/rules_generated.rs"));
}

/// Every rule: code rules, then declarative rules.
pub fn all() -> &'static [&'static dyn Rule] {
    generated::ALL
}

/// The rule with this ID.
pub fn get(id: &str) -> Option<&'static dyn Rule> {
    all().iter().copied().find(|r| r.meta().id == id)
}

/// Metadata of every rule, sorted by ID.
pub fn list() -> Vec<RuleInfo> {
    let mut v: Vec<RuleInfo> = all().iter().map(|r| *r.meta()).collect();
    v.sort_by_key(|m| m.id);
    v
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::rules::meta::{Action, is_valid_rule_id};
    use std::collections::HashSet;

    #[test]
    fn ids_unique_and_well_formed() {
        let mut seen = HashSet::new();
        for r in all() {
            let m = r.meta();
            assert!(is_valid_rule_id(m.id), "{}", m.id);
            assert!(seen.insert(m.id), "duplicate rule ID {}", m.id);
            let prefix = m.id.split('.').next().unwrap();
            assert_eq!(prefix, m.category.prefix(), "{}: prefix vs category", m.id);
            if m.locked {
                assert_eq!(m.default_action, Action::Block, "{}: locked", m.id);
            }
            for s in [m.since, m.message, m.description] {
                assert!(!s.trim().is_empty(), "{}: empty metadata", m.id);
            }
        }
    }

    #[test]
    fn sample_rules_registered() {
        let ids: Vec<_> = list().iter().map(|m| m.id).collect();
        for id in ["ACTIVE.LAUNCH", "FILETYPE.NOT_PDF_HEADER"] {
            assert!(ids.contains(&id), "{id} missing: {ids:?}");
        }
        assert!(ids.windows(2).all(|w| w[0] < w[1]), "sorted");
        assert_eq!(
            get("ACTIVE.LAUNCH").map(|r| r.meta().id),
            Some("ACTIVE.LAUNCH")
        );
        assert!(get("ACTIVE.NOPE").is_none());
    }

    /// The testkit's copy of design §5.7 computes the manifest's expected
    /// verdicts: a registered rule must exist there with the same `locked`.
    #[test]
    fn rules_match_testkit_spec() {
        for m in list() {
            let spec = quelda_testkit::rules::RULES
                .iter()
                .find(|s| s.id == m.id)
                .unwrap_or_else(|| {
                    panic!("{} is not in design §5.7 (quelda_testkit::rules)", m.id)
                });
            assert_eq!(spec.locked, m.locked, "{}: locked", m.id);
            assert_eq!(
                quelda_testkit::rules::category_of(m.id),
                Some(m.category.key()),
                "{}: category",
                m.id
            );
            let balanced =
                quelda_testkit::rules::action(m.id, quelda_testkit::rules::Preset::Balanced);
            assert_eq!(
                balanced.key(),
                m.default_action.key(),
                "{}: default_action",
                m.id
            );
        }
    }
}
